'use strict';
const designedHome=homeHTML;
homeHTML=function(){const box=document.createElement('div');box.innerHTML=designedHome();const landing=box.querySelector('.landing'),intro=box.querySelector('.landing-intro'),stage=box.querySelector('.showcase');if(landing&&intro&&stage){const hero=document.createElement('section');hero.className='vivid-hero';landing.prepend(hero);hero.append(intro,stage);intro.querySelector('h1').innerHTML='عميل اليوم.<br><span>عميل كل يوم.</span>';intro.querySelector('.landing-kicker').textContent='كل رجعة تبدأ بتجربة';const copy=document.createElement('div');copy.className='hero-copy';while(intro.firstChild)copy.append(intro.firstChild);intro.append(copy);intro.insertAdjacentHTML('beforeend','<aside class=hero-services aria-label=خدمات-رجعة><div class=service-line><span class=service-symbol aria-hidden=true>✦</span><div><h2>بطاقات ولاء باسمك</h2><p>زيارات، خصومات أو نقاط. اختر ما يناسب نشاطك.</p></div></div><div class=service-line><span class=service-symbol aria-hidden=true>▣</span><div><h2><bdi>Apple Wallet</bdi> و<bdi>Google Wallet</bdi></h2><p>بطاقة العميل معه على جواله.</p><small class=service-status>ربط المحافظ قيد التجهيز</small></div></div><div class=service-line><span class=service-symbol aria-hidden=true>⌘</span><div><h2>فروعك وفريقك، في مكان واحد</h2><p>اربط الموظفين بالبطاقات والفروع، وتابع أداء كل فرع.</p></div></div><div class=service-line><span class=service-symbol aria-hidden=true>◈</span><div><h2>تصميم يحمل هويتك</h2><p>خلفيتك وشعارك وعناصر الولاء، بحرية في الترتيب والحجم.</p></div></div><div class=service-line><span class=service-symbol aria-hidden=true>↗</span><div><h2>أرقام توضح نمو نشاطك</h2><p>زيارات، مكافآت ومبالغ مسجلة، بحسب البطاقة والفرع والفترة.</p></div></div></aside>');hero.insertAdjacentHTML('beforeend','<div class=gallery-heading><span>01 / بطاقاتك</span><h2>ثلاث طرق. ولاء واحد.</h2><p>حرّك المعرض واكتشف شكل برنامجك القادم.</p></div>');hero.append(stage);stage.classList.add('showcase-3d','media-gallery');stage.setAttribute('aria-label','معرض بطاقات الولاء');const track=document.createElement('div');track.className='card-ring';stage.querySelectorAll('.showcase-item').forEach(el=>track.append(el));stage.append(track);stage.insertAdjacentHTML('beforeend','<p class="gallery-hint">حرّك الماوس أو اسحب لاستكشاف البطاقات</p>');}box.querySelectorAll('.premium-plan').forEach((article,i)=>{article.classList.add('folder-plan');const cover=document.createElement('button');cover.type='button';cover.className='folder-cover';cover.setAttribute('aria-expanded','false');cover.setAttribute('aria-controls',`folder-details-${i}`);['.plan-top','.plan-description','.plan-price-line','.price'].forEach(selector=>cover.append(article.querySelector(selector)));cover.insertAdjacentHTML('beforeend','<span class="folder-hint">اكتشف مميزات الباقة ↗</span>');const details=document.createElement('div');details.className='folder-details';details.id=`folder-details-${i}`;details.hidden=true;details.append(article.querySelector('.feature-list'),article.querySelector('[data-action=choose-plan]'),article.querySelector('small'));article.append(details,cover);});return box.innerHTML;};
function bindGallery(){const stage=document.querySelector('.media-gallery');if(!stage)return;const items=Array.from(stage.querySelectorAll('.showcase-item'));let position=0,startX=null,startPosition=0,frame=null;const layout=()=>{items.forEach((el,i)=>{const relative=i-position;const spacing=Math.min(330,Math.max(230,stage.clientWidth/3));el.style.setProperty('--gallery-x',`${relative*spacing}px`);el.style.setProperty('--gallery-z',`${Math.max(5,100-Math.abs(relative)*60)}px`);el.style.setProperty('--gallery-angle',`${Math.max(-24,Math.min(24,-relative*17))}deg`);});};const update=value=>{position=Math.max(0,Math.min(items.length-1,value));if(frame===null)frame=requestAnimationFrame(()=>{frame=null;layout();});};stage.tabIndex=0;stage.setAttribute('aria-label','معرض بطاقات الولاء، استخدم السحب أو مفاتيح الأسهم');stage.addEventListener('pointermove',e=>{if(e.target.closest('button')||(startX===null&&e.clientY>stage.getBoundingClientRect().top+350))return;if(startX!==null){update(startPosition+(startX-e.clientX)/240);}else if(e.pointerType==='mouse'&&e.target.closest('.studio-card')){const bounds=stage.getBoundingClientRect();stage.style.setProperty('--pointer-tilt',`${(e.clientX-bounds.left)/bounds.width*8-4}deg`);}});stage.addEventListener('pointerdown',e=>{if(!e.isPrimary||e.target.closest('button'))return;startX=e.clientX;startPosition=position;stage.setPointerCapture(e.pointerId);});const end=e=>{if(e.target.closest('button'))return;startX=null;update(Math.round(position));};stage.addEventListener('pointerup',end);stage.addEventListener('pointercancel',end);stage.addEventListener('keydown',e=>{if(e.key==='ArrowRight'||e.key==='ArrowLeft'){e.preventDefault();update(Math.round(position)+(e.key==='ArrowRight'?1:-1));}});const resizeObserver=new ResizeObserver(layout);resizeObserver.observe(stage);stage._cleanup=()=>{resizeObserver.disconnect();if(frame!==null)cancelAnimationFrame(frame);};position=(items.length-1)/2;layout();}
function bindFolders(){document.querySelectorAll('.folder-plan').forEach(article=>{const cover=article.querySelector('.folder-cover'),content=article.querySelector('.folder-details');let pinned=false;const open=value=>{article.classList.toggle('folder-open',value);cover.setAttribute('aria-expanded',String(value));content.hidden=!value;};article.addEventListener('pointerenter',e=>{if(e.pointerType==='mouse')open(true);});article.addEventListener('pointerleave',e=>{if(e.pointerType==='mouse'&&!pinned&&!article.contains(document.activeElement))open(false);});cover.addEventListener('click',()=>{pinned=!pinned;open(pinned);});article.addEventListener('focusin',()=>open(true));article.addEventListener('focusout',e=>{if(!article.contains(e.relatedTarget)&&!pinned)open(false);});article.addEventListener('keydown',e=>{if(e.key==='Escape'){pinned=false;open(false);cover.focus();}});});}
const brandedRender=render;
render=function(){document.querySelector('.media-gallery')?._cleanup?.();brandedRender();document.querySelectorAll('.brand').forEach(el=>{el.innerHTML='<img class="rijaa-brand-logo" src="/brand-logo.png" alt="رجعة — نظام الولاء" width="240" height="96">';});document.querySelectorAll('.public-brand').forEach(el=>{el.innerHTML='<span class="ocean-brand-lockup"><img class="rijaa-brand-logo" src="/brand-logo.png" alt="رجعة — نظام الولاء" width="240" height="96"><img class="rijaa-brand-logo brand-white-word" src="/brand-logo.png" alt="" aria-hidden="true" width="240" height="96"></span>';});document.querySelectorAll(".public-nav .btn,.landing-intro .btn,.auth-panel button[type=submit]").forEach(b=>{const text=b.textContent.trim();b.classList.add("glow-button");b.innerHTML=`<span class="glow-orbit" aria-hidden="true"><span>↗</span></span><span class="glow-label">${esc(text)}</span>`;});bindGallery();bindFolders();};
render();



